from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from .api.routes import router
from .api.signals import router as signals_router
from .api.live import router as live_router
from .db import init_db

app=FastAPI(title="Qanas Data Engine",version="0.4.2")
@app.on_event("startup")
def startup(): init_db()
app.include_router(router,prefix="/api")
app.include_router(signals_router,prefix="/api")
app.include_router(live_router,prefix="/api")

DASHBOARD_HTML=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>قنص</title><style>
:root{--bg:#071019;--panel:#0b1722;--line:#193041;--text:#edf5f8;--muted:#8296a5;--gold:#f0d18b;--green:#4bd39a;--cyan:#5cc8ff;--amber:#ffbd59}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Segoe UI,Tahoma,Arial}.wrap{max-width:1600px;margin:auto;padding:24px}.top,.toolbar,.actions,.chips{display:flex;gap:10px;align-items:center}.top{justify-content:space-between;margin-bottom:20px}.brand{display:flex;gap:14px;align-items:center}.mark{width:54px;height:54px;border:1px solid #55472d;border-radius:17px;display:grid;place-items:center;font-size:25px;color:var(--gold);font-weight:900}h1{margin:0}.muted,.company{color:var(--muted)}.btn,.chip{border:1px solid var(--line);background:#0d1a26;color:var(--text);padding:10px 14px;border-radius:12px;cursor:pointer}.btn.gold,.chip.active{background:var(--gold);color:#111}.hero{display:grid;grid-template-columns:1.4fr .6fr;gap:16px;margin-bottom:16px}.hero>div,.stat{border:1px solid var(--line);background:var(--panel);border-radius:18px;padding:20px}.hero h2{font-size:32px;margin:8px 0}.syncrow{display:flex;justify-content:space-between;margin:8px 0}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}.stat span{font-size:12px;color:var(--muted)}.stat b{display:block;font-size:24px;margin-top:7px}.toolbar{justify-content:space-between;border:1px solid var(--line);background:var(--panel);padding:12px;border-radius:16px 16px 0 0;overflow:auto}.search{min-width:250px;flex:1}.search input{width:100%;background:#08141e;border:1px solid #1e3546;color:white;border-radius:11px;padding:11px}.chips{white-space:nowrap}.tablebox{border:1px solid var(--line);border-top:0;overflow:auto}table{width:100%;border-collapse:collapse;min-width:1500px}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th{font-size:11px;color:#6f8798;background:#0b1924}.ticker{font-size:16px;font-weight:900}.company{font-size:11px}.good,.rise,.live{color:var(--green);font-weight:900}.nearready{color:var(--amber);font-weight:900}.goldtext{color:var(--gold);font-weight:800}.rebate{color:var(--cyan);font-weight:800}.pill{border:1px solid #244052;padding:5px 8px;border-radius:8px}.empty{text-align:center;padding:50px;color:var(--muted)}tbody tr{cursor:pointer}.drawer{position:fixed;inset:0;background:#0009;display:none;z-index:50}.drawer.open{display:block}.sheet{position:absolute;left:0;top:0;height:100%;width:min(540px,94vw);background:#09151f;padding:24px;overflow:auto}.close{float:left;background:none;border:0;color:white;font-size:26px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.mini{border:1px solid var(--line);border-radius:12px;padding:12px}.mini span{display:block;color:var(--muted);font-size:11px}.histrow{display:grid;grid-template-columns:1.3fr .8fr .8fr .8fr;gap:8px;padding:9px;border-bottom:1px solid var(--line)}.toast{position:fixed;bottom:20px;right:20px;background:#102330;padding:12px;border:1px solid #2c4658;border-radius:10px;display:none}.toast.show{display:block}@media(max-width:900px){.hero{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="mark">ق</div><div><h1>قنص</h1><small class="muted">Reverse Split Intelligence</small></div></div><div class="actions"><button class="btn" onclick="loadData()">تحديث العرض</button><button id="borrowBtn" class="btn gold" onclick="startBorrowSync()">تحديث Available + CTB + Rebate</button></div></div>
<section class="hero"><div><div class="goldtext">QANAS / LIVE BOARD</div><h2>القنص بالركادة.</h2><p class="muted">Available وCTB وRebate مع القاع والثبات وإشارات الجاهزية.</p></div><div><div class="syncrow"><span>حالة البيانات</span><strong id="syncState">متصل</strong></div><div class="syncrow"><span>آخر Borrow</span><strong id="lastBorrow">—</strong></div><div class="syncrow"><span>السعر الحالي</span><strong class="good">يشمل الممتد ✓</strong></div></div></section>
<section class="stats"><div class="stat"><span>أسهم فعالة</span><b id="sTotal">—</b></div><div class="stat"><span>Available ≤ 10K</span><b id="sScarce">—</b></div><div class="stat"><span>وصلت النصف</span><b id="sHalf">—</b></div><div class="stat"><span>قريبة من القاع ≤10%</span><b id="sNear">—</b></div><div class="stat"><span>جاهزة / شبه جاهزة</span><b id="sReady">—</b></div></section>
<div class="toolbar"><div class="search"><input id="q" placeholder="ابحث بالرمز أو اسم الشركة..." oninput="render()"></div><div class="chips"><button class="chip active" onclick="setFilter('all',this)">الكل</button><button class="chip" onclick="setFilter('scarce',this)">Available منخفض</button><button class="chip" onclick="setFilter('half',this)">وصل النصف</button><button class="chip" onclick="setFilter('near',this)">قريب من القاع</button><button class="chip" onclick="setFilter('ready',this)">🎯 جاهزة للدخول</button><button class="chip" onclick="setFilter('launched',this)">🚀 انطلقت +40%</button></div></div>
<div class="tablebox"><table><thead><tr><th>السهم</th><th>الجاهزية</th><th>Available</th><th>CTB</th><th>Rebate</th><th>السعر الحالي</th><th>القاع</th><th>عن القاع</th><th>القمة</th><th>النصف</th><th>الثبات</th><th>الارتفاع بعد الجاهزية</th><th>وش باقي؟</th><th>تاريخ الجاهزية/الانطلاق</th><th>التقسيم</th></tr></thead><tbody id="rows"></tbody></table></div></div>
<div id="drawer" class="drawer" onclick="if(event.target===this)closeDrawer()"><div class="sheet"><button class="close" onclick="closeDrawer()">×</button><div id="detail"></div></div></div><div id="toast" class="toast"></div><script>
let data=[],signals={},live={},filter='all';const fmt=n=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:2}),money=n=>n==null?'—':'$'+Number(n).toFixed(4),pct=n=>n==null?'—':Number(n).toFixed(2)+'%';function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3000)}function setFilter(f,e){filter=f;document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));e.classList.add('active');render()}async function loadData(){try{syncState.textContent='يتم التحديث...';const [d,s,l]=await Promise.all([fetch('/api/hunt').then(r=>r.json()),fetch('/api/signals').then(r=>r.json()),fetch('/api/live-prices').then(r=>r.json())]);signals=Object.fromEntries(s.map(x=>[x.symbol,x]));live=Object.fromEntries(l.map(x=>[x.symbol,x]));data=d.map(x=>({...x,signal:signals[x.symbol]||null,live:live[x.symbol]||null}));syncState.textContent='متصل';summary();render()}catch(e){syncState.textContent='خطأ اتصال'}}function summary(){sTotal.textContent=data.length;sScarce.textContent=data.filter(x=>x.available!=null&&x.available<=10000).length;sHalf.textContent=data.filter(x=>x.half_level_reached).length;sNear.textContent=data.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10).length;sReady.textContent=data.filter(x=>x.signal?.ready||x.signal?.near_ready).length;const d=data.map(x=>x.borrow_timestamp).filter(Boolean).sort().pop();lastBorrow.textContent=d?new Date(d+'Z').toLocaleString('ar-SA'):'—'}function render(){let a=data,q=document.getElementById('q').value.trim().toUpperCase();a=a.filter(x=>!q||x.symbol.includes(q)||(x.company||'').toUpperCase().includes(q));if(filter==='scarce')a=a.filter(x=>x.available!=null&&x.available<=10000);if(filter==='half')a=a.filter(x=>x.half_level_reached);if(filter==='near')a=a.filter(x=>x.distance_from_low_pct!=null&&x.distance_from_low_pct<=10);if(filter==='ready')a=a.filter(x=>x.signal?.ready||x.signal?.near_ready);if(filter==='launched')a=a.filter(x=>x.signal?.launched);a.sort((a,b)=>filter==='launched'?(b.signal?.rise_pct||0)-(a.signal?.rise_pct||0):filter==='ready'?((b.signal?.ready?2:1)-(a.signal?.ready?2:1))||((b.ready_score||0)-(a.ready_score||0)):(b.ready_score||0)-(a.ready_score||0));rows.innerHTML=a.length?a.map(x=>{let s=x.signal,dt=s?.launched_at||s?.ready_at,lp=x.live?.live_price,shown=lp??x.current_price,status=s?.ready?'100% 🎯':s?.near_ready?'شبه جاهز':'—',missing=s?.ready?'مكتمل ✓':s?.missing||'—';return `<tr onclick="openStock('${x.symbol}')"><td><b class="ticker">${x.symbol}</b><div class="company">${x.company||''}</div></td><td class="${s?.ready?'good':s?.near_ready?'nearready':''}">${status}<div class="company">سكور ${fmt(x.ready_score)}</div></td><td class="${x.available<=10000?'good':''}">${fmt(x.available)}</td><td class="goldtext">${pct(x.ctb)}</td><td class="rebate">${pct(x.rebate_rate)}</td><td class="${lp!=null?'live':''}">${money(shown)}<div class="company">${lp!=null?'LIVE · ممتد':'آخر إغلاق'}</div></td><td>${money(x.post_split_low)}</td><td>${pct(x.distance_from_low_pct)}</td><td>${money(x.post_split_high)}</td><td><span class="pill">${money(x.half_level)} ${x.half_level_reached?'✓':''}</span></td><td>${fmt(x.stability_sessions)} / 4</td><td class="rise">${s?.rise_pct!=null?pct(s.rise_pct):'—'}</td><td class="${s?.near_ready?'nearready':''}">${missing}</td><td>${dt?new Date(dt+'Z').toLocaleDateString('ar-SA'):'—'}<div class="company">${s?.launched?'انطلق':s?.ready?'جاهز':s?.near_ready?'قريب جدًا':''}</div></td><td>${x.ratio}<div class="company">${x.effective_date}</div></td></tr>`}).join(''):'<tr><td colspan="15" class="empty">لا توجد نتائج</td></tr>'}async function openStock(symbol){drawer.classList.add('open');detail.innerHTML='<div class="empty">جاري التحميل...</div>';try{const [s,h]=await Promise.all([fetch('/api/stock/'+symbol).then(r=>r.json()),fetch('/api/borrow/'+symbol+'/history?limit=12').then(r=>r.json())]),g=signals[symbol],l=live[symbol];detail.innerHTML=`<h2>${s.symbol}</h2><div class="muted">${s.company||''}</div>${g?.near_ready?`<div class="mini nearready"><span>وش باقي للجاهزية؟</span><b>${g.missing}</b></div>`:''}<div class="grid2"><div class="mini"><span>السعر الحالي · الممتد</span><b class="live">${money(l?.live_price??s.current_price)}</b></div><div class="mini"><span>آخر إغلاق يومي</span><b>${money(s.current_price)}</b></div><div class="mini"><span>Available</span><b>${fmt(s.available)}</b></div><div class="mini"><span>CTB</span><b>${pct(s.ctb)}</b></div><div class="mini"><span>Rebate</span><b class="rebate">${pct(s.rebate_rate)}</b></div><div class="mini"><span>ارتفاع بعد الجاهزية</span><b class="rise">${g?.rise_pct!=null?pct(g.rise_pct):'—'}</b></div><div class="mini"><span>سعر الجاهزية</span><b>${g?.ready_price?money(g.ready_price):'—'}</b></div><div class="mini"><span>أعلى سعر بعدها</span><b>${g?.max_price_after_ready?money(g.max_price_after_ready):'—'}</b></div></div><h3>آخر قراءات الاقتراض</h3>${h.map(r=>`<div class="histrow"><span>${new Date(r.timestamp+'Z').toLocaleString('ar-SA')}</span><b>${fmt(r.available)}</b><b>${pct(r.ctb)}</b><b class="rebate">${pct(r.rebate_rate)}</b></div>`).join('')}`}catch(e){detail.innerHTML='تعذر التحميل'}}function closeDrawer(){drawer.classList.remove('open')}async function startBorrowSync(){borrowBtn.disabled=true;await fetch('/api/sync/borrow/all');pollBorrow()}async function pollBorrow(){const s=await fetch('/api/sync/borrow/status').then(r=>r.json());borrowBtn.textContent=s.running?`تحديث ${s.processed}/${s.total}`:'تحديث Available + CTB + Rebate';if(s.running)setTimeout(pollBorrow,1500);else{borrowBtn.disabled=false;toast('اكتمل التحديث');loadData()}}loadData();setInterval(loadData,60000);
</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def dashboard(): return HTMLResponse(DASHBOARD_HTML)
